async fn exec_plan_fragment(
    &self,
    request: PExecPlanFragmentRequest,
    attachment: Vec<u8>,
) -> Result<crate::prpc::Reply<PExecPlanFragmentResult>, crate::prpc::Error> {
    // Translate + execute on a blocking worker, not the BRPC current-thread runtime: a real GPU
    // executor blocks for the whole query, so running it inline would stall fetch_data,
    // connection cleanup, and shutdown cancellation until it returns.
    let protocol = request.attachment_protocol;
    let service = self.clone();
    let outcome = tokio::task::spawn_blocking(move || {
        service.exec_single_attachment(protocol.as_deref(), &attachment)
    })
    .await;
    let status = match outcome {
        Ok(Ok(())) => Self::ok_status(),
        Ok(Err(err)) => Self::internal_error(err),
        Err(join_err) => {
            Self::internal_error(format!("fragment execution task panicked: {join_err}"))
        }
    };
    Ok(Self::exec_plan_result(status).into())
}

/// Handles FE batch fragment dispatch: translate every per-instance fragment and execute the
/// RESULT_SINK roots among them.
#[instrument(skip_all)]
async fn exec_batch_plan_fragments(
    &self,
    request: PExecBatchPlanFragmentsRequest,
    attachment: Vec<u8>,
) -> Result<crate::prpc::Reply<PExecBatchPlanFragmentsResult>, crate::prpc::Error> {
    // Like `exec_plan_fragment`, an instance can run a RESULT_SINK fragment on the GPU, so
    // offload to a blocking worker rather than blocking the BRPC current-thread runtime.
    let protocol = request.attachment_protocol;
    let service = self.clone();
    let outcome = tokio::task::spawn_blocking(move || {
        service.translate_batch_attachment(protocol.as_deref(), &attachment)
    })
    .await;
    let status = match outcome {
        Ok(Ok(())) => Self::ok_status(),
        Ok(Err(err)) => Self::internal_error(err),
        Err(join_err) => Self::internal_error(format!(
            "batch fragment execution task panicked: {join_err}"
        )),
    };
    Ok(PExecBatchPlanFragmentsResult {
        status: Some(status),
    }
    .into())
}

/// Best-effort cancellation stub: acknowledges the FE with OK so its shared jprotobuf
/// channel stays healthy — the default unrouted reply is a PRPC-level error frame, and the
/// FE reaps the timed-out future in a way that misattributes later replies on the channel.
/// A still-waiting result entry is failed so a `fetch_data` long-poll returns immediately.
/// Real teardown (aborting the engine run, freeing GPU buffers, dropping parked exchange
/// state) is a separate work item.
#[instrument(skip_all)]
async fn cancel_plan_fragment(
    &self,
    request: PCancelPlanFragmentRequest,
    _attachment: Vec<u8>,
) -> Result<crate::prpc::Reply<PCancelPlanFragmentResult>, crate::prpc::Error> {
    let id = FragmentInstanceId::from(&request.finst_id);
    info!(
        fragment_instance_id = %id,
        query_id = ?request.query_id.as_ref().map(FragmentInstanceId::from),
        cancel_reason = request.cancel_reason,
        error_message = ?request.error_message,
        "acknowledging cancel_plan_fragment (best-effort: no engine-side abort yet)"
    );
    let mut reason = format!("fragment instance {id} was cancelled by the FE");
    if let Some(message) = request.error_message.as_ref().filter(|msg| !msg.is_empty()) {
        reason = format!("{reason}: {message}");
    }
    self.core.results.cancel(id, reason);
    Ok(PCancelPlanFragmentResult {
        status: Self::ok_status(),
    }
    .into())
}

/// Returns buffered fragment results to the FE, which polls this until end-of-stream. The
/// serialized `TResultBatch` rows ride in the BRPC response attachment.
#[instrument(skip_all)]
async fn fetch_data(
    &self,
    request: PFetchDataRequest,
    _attachment: Vec<u8>,
) -> Result<crate::prpc::Reply<PFetchDataResult>, crate::prpc::Error> {
    let id = FragmentInstanceId::from(&request.finst_id);
    // Long-poll: receivers execute on the dispatch thread now, so a reserved result may not
    // be ready when the FE's first poll arrives. Block off the runtime until it is — every
    // reply consumes a packet-sequence slot in the FE's ResultReceiver, so a not-ready reply
    // would desync the counter and cancel the query ("expect=1, receive=0").
    let core = self.core.clone();
    let outcome = match tokio::task::spawn_blocking(move || {
        core.results
            .wait_ready(id, std::time::Duration::from_secs(600))
    })
    .await
    {
        Ok(outcome) => outcome,
        Err(join_err) => {
            return Ok(Self::fetch_data_result(
                Self::internal_error(format!("fetch_data wait task panicked: {join_err}")),
                0,
                true,
            )
            .into());
        }
    };
    // An unknown id is an error, not EOS: it means this CN never buffered a result for the
    // fragment the FE is polling (wrong id, or a dispatch/result-sink path that did not run),
    // and StarRocks treats a missing result buffer as a failure rather than an empty result.
    let Some(outcome) = outcome else {
        return Ok(Self::fetch_data_result(
            Self::internal_error(format!("no buffered result for fragment instance {id}")),
            0,
            true,
        )
        .into());

}

/// Runs one dispatched receiver, parking a failure where `fetch_data` can see it. Returns
/// the next receiver when this fragment's own sink completed another sender set.
fn run_ready_fragment(&self, ready: ReadyFragment) -> Vec<ReadyFragment> {
    let id = Self::fragment_instance_id(&ready.params);
    let query_id = Self::query_id(&ready.params);
    let is_result_fragment = matches!(Self::is_mysql_result_sink(&ready.params), Ok(true));
    // `join_into_ready` keeps this fragment's own remote drains inside this call, so a drain
    // failure is attributed to the same query as any other failure of this fragment.
    match self
        .execute_ready_fragment(ready)
        .and_then(FragmentOutcome::join_into_ready)
    {
        Ok(next) => next,
        Err(error) => {
            match (id, query_id) {
                (Some(id), Some(query_id)) => {
                    if is_result_fragment {
                        // The FE polls fetch_data on this id; its reserved entry becomes
                        // the error instead of waiting forever.
                        tracing::error!(fragment_instance_id = %id, error = %error, "dispatched result fragment failed");
                    } else {
                        // An intermediate receiver has no FE-polled entry of its own, so
                        // its failure must reach the query's result-fragment instances —
                        // otherwise the FE polls until its timeout and the stalled
                        // fetch_data wedges this CN's whole frame loop.
                        tracing::error!(
                            fragment_instance_id = %id,
                            error = %error,
                            "dispatched intermediate receiver fragment failed; failing the query's result fragments"
                        );
                    }
                    // Fails this id, every reserved result instance of the query, and
                    // records the failure so a result fragment arriving later fails on
                    // registration instead of waiting on senders that never deliver.
                    self.results.fail_query(query_id, id, error);
                }
                (Some(id), None) => {
                    // Defensive: exec params carry both ids or neither, so this arm should
                    // be unreachable. Park the error under the instance id at least.
                    tracing::error!(fragment_instance_id = %id, error = %error, "dispatched receiver fragment without a query_id failed");
                    self.results.fail(id, error);
                }
                (None, _) => {
                    tracing::error!(error = %error, "dispatched receiver fragment without a fragment_instance_id failed");
                }
            }
            Vec::new()
        }
    }
}

/// Processes one fragment and buffers supported RESULT_SINK rows for later `fetch_data`.
/// Shared by single and batch dispatch; exchange receivers are registered until their local
/// sender output is materialized. Returns a receiver whose sender set this fragment
/// completed — the caller decides where it executes (RPC handlers hand it to the dispatch
/// worker; the worker itself runs it inline).
fn process_fragment(
    &self,
    params: &TExecPlanFragmentParams,
) -> std::result::Result<FragmentOutcome, String> {
    let params = self.resolve_descriptor_table(params)?;
    let dump_seq = Self::dump_fragment(&params);
    // Survey mode: accept every fragment so the FE dispatches (and we dump) the whole
    // plan even when translation fails. Queries still fail at fetch_data.
    if std::env::var_os("SIRIUS_CN_TRANSLATE_ONLY").is_some() {
        if let Err(err) = self.translate_fragment_logged(&params, dump_seq) {
            tracing::warn!(error = %err, "translate-only mode: accepting untranslatable fragment");
        }
        return Ok(FragmentOutcome::default());
    }
    let expected_senders = Self::receiver_exchanges(&params)?;
    if !expected_senders.is_empty() {
        let fragment_instance_id = Self::fragment_instance_id(&params)
            .ok_or_else(|| "exchange receiver is missing a fragment_instance_id".to_string())?;
        if Self::is_mysql_result_sink(&params)? {
            let query_id = Self::query_id(&params)
                .ok_or_else(|| "exchange receiver is missing a query_id".to_string())?;
            self.results.reserve(fragment_instance_id, query_id);
        }
        return Ok(FragmentOutcome::from_ready(
            self.exchanges
                .register_receiver(fragment_instance_id, expected_senders, params)?
                .into_iter()
                .collect(),
        ));
    }

    let translated = self.translate_fragment_logged(&params, dump_seq)?;
    self.execute_fragment(&params, translated)
}

/// Restores descriptor tables omitted by StarRocks's per-query descriptor cache protocol.
fn resolve_descriptor_table(
    &self,
    params: &TExecPlanFragmentParams,
) -> std::result::Result<TExecPlanFragmentParams, String> {
    let mut resolved = params.clone();
    let Some(query_id) = params
        .params
        .as_ref()
        .map(|exec| FragmentInstanceId::from(&exec.query_id))
    else {
        return Ok(resolved);
    };
    let Some(desc) = params.desc_tbl.as_ref() else {
        return Ok(resolved);
    };
    let is_cached_reference = desc.is_cached == Some(true)
        && desc.slot_descriptors.as_ref().is_none_or(Vec::is_empty)
        && desc.tuple_descriptors.is_empty()
        && desc.table_descriptors.as_ref().is_none_or(Vec::is_empty);
    let mut cache = self
        .descriptor_tables
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if is_cached_reference {
        resolved.desc_tbl = Some(
            cache
                .get(&query_id)
                .cloned()
                .ok_or_else(|| format!("descriptor table cache miss for query {query_id}"))?,
        );
    } else {
        cache.insert(query_id, desc.clone());
    }
    Ok(resolved)
}

/// Writes the received fragment params to `$SIRIUS_CN_DUMP_FRAGMENTS/fragment-<seq>.txt`
/// (debug format) for offline plan analysis. No-op when the variable is unset.
fn dump_fragment(params: &TExecPlanFragmentParams) -> Option<u64> {
    use std::sync::atomic::{AtomicU64, Ordering};
    let Ok(dir) = std::env::var("SIRIUS_CN_DUMP_FRAGMENTS") else {
        return None;
    };
    static SEQ: AtomicU64 = AtomicU64::new(0);
    let seq = SEQ.fetch_add(1, Ordering::Relaxed);
    let path = std::path::Path::new(&dir).join(format!("fragment-{seq:04}.txt"));
    if let Err(err) = std::fs::write(&path, format!("{params:#?}")) {
        tracing::warn!(error = %err, path = %path.display(), "failed to dump fragment params");
    }
    Some(seq)
}

/// Executes a fragment that reads no exchange input.
fn execute_fragment(
    &self,
    params: &TExecPlanFragmentParams,
    translated: TranslatedPlan,
) -> std::result::Result<FragmentOutcome, String> {
    self.execute_fragment_with_inputs(params, translated, Vec::new(), Vec::new())
}

/// Executes a result fragment, or runs a data-stream sender and parks its output on the GPU
/// for its local receiver (transmitting it when the receiver is remote). `inputs` names the
/// parked sender outputs this fragment consumes; `remote_inputs` the staged remote batches.
/// A sender that completes its receiver's sender set returns that receiver for the caller
/// to run or dispatch, alongside the remote drains the caller must join.
fn execute_fragment_with_inputs(
    &self,
    params: &TExecPlanFragmentParams,
    translated: TranslatedPlan,
    inputs: Vec<(i32, Vec<SenderSlot>)>,
    remote_inputs: Vec<(i32, i32, Vec<StagedBatch>)>,
) -> std::result::Result<FragmentOutcome, String> {
    if Self::is_mysql_result_sink(params)? {
        let id = Self::fragment_instance_id(params).ok_or_else(|| {
            "RESULT_SINK fragment is missing a fragment_instance_id".to_string()
        })?;
        let result = self
            .run_labeled(
                "result",
                FragmentRun {
                    plan: &translated,
                    inputs: inputs.clone(),
                    remote_inputs,
                    outputs: Vec::new(),
                    broadcast: false,
                    hash_keys: Vec::new(),
                    label: Self::fragment_label(params),
                },
            )?
            .ok_or_else(|| "result fragment returned no rows".to_string())?;
        let batch = result_encoder::MysqlResultEncoder::encode(&result.batches, 0)?;
        self.results.insert(id, batch);
        return Ok(FragmentOutcome::default());
    }

    let Some(sink) = params
        .fragment
        .as_ref()
        .and_then(|fragment| fragment.output_sink.as_ref())
    else {
        // The FE attaches a sink to every fragment it dispatches (PlanFragment.toThrift),
        // so a sinkless fragment only reaches here from a translate-only fixture.
        tracing::warn!(
            fragment = %Self::fragment_context(params),
            "fragment carries no output sink; nothing consumes its output"
        );
        return Ok(FragmentOutcome::default());
    };
    // Accepting an unhandled sink discards the fragment's whole output: its consumers wait
    // forever, the FE's fetch_data long-poll times out, and its serial channel wedges
    // cluster-wide. Refuse by name so the FE error says which plan shape is unsupported.
    if sink.type_ != TDataSinkType::DATA_STREAM_SINK {
        return Err(format!(
            "{} carries a {} output sink, which this CN does not support",
            Self::fragment_context(params),
            Self::data_sink_type_name(sink.type_)
        ));
    }
    let stream_sink = sink.stream_sink.as_ref().ok_or_else(|| {
        format!(
            "{} carries a DATA_STREAM_SINK with no stream_sink payload",
            Self::fragment_context(params)
        )
    })?;
    if stream_sink.limit.is_some_and(|limit| limit >= 0) {
        return Err("data stream sink limits are not supported".to_string());
    }
    if let Some(columns) = stream_sink
        .output_columns
        .as_ref()
        .filter(|columns| !columns.is_empty())
        && columns
            .iter()
            .copied()
            .ne(0..translated.output_names.len() as i32)
    {
        return Err(
            "non-identity data stream sink output_columns are not supported".to_string(),
        );
    }
    let exec = params
        .params
        .as_ref()
        .ok_or_else(|| "DATA_STREAM_SINK fragment is missing execution params".to_string())?;
    let destinations = exec
        .destinations
        .as_ref()
        .filter(|destinations| !destinations.is_empty())
        .ok_or_else(|| "DATA_STREAM_SINK fragment has no destinations".to_string())?;
    let sender_id = exec.sender_id.unwrap_or(0);
    // Fan-out shape: one destination is a gather regardless of the partition label;
    // UNPARTITIONED with N destinations broadcasts the full output to every receiver
    // (each destination drains its own copy from its own output stream). Hash-partitioned
    // fan-out is the second half of #838 and still refuses.
    if destinations.len() > 1 {
        use starrocks_thrift::partitions::TPartitionType;
        match stream_sink.output_partition.type_ {
            TPartitionType::UNPARTITIONED => {}
            TPartitionType::HASH_PARTITIONED => {
                if translated.output_partition_columns.is_none() {
                    return Err(
                        "a hash-partitioned data stream sink translated without partition \
                         key columns"
                            .to_string(),
                    );
                }

                }
            }
            other => {
                return Err(format!(
                    "a data stream sink with {} destinations carries partition type {:?}, \
                     which this CN does not support",
                    destinations.len(),
                    other
                ));
            }
        }
    }
    let hash_keys = if destinations.len() > 1 {
        translated
            .output_partition_columns
            .clone()
            .unwrap_or_default()
    } else {
        Vec::new()
    };
    let broadcast = destinations.len() > 1 && hash_keys.is_empty();

    // Route every destination BEFORE running: a remote destination without a transport (or
    // a duplicate) must fail before any GPU work happens. Destination i then drains the
    // sender's output stream i -- the FE's destination order, positionally.
    let mut slots: Vec<SenderSlot> = Vec::with_capacity(destinations.len());
    let mut routes = Vec::with_capacity(destinations.len());
    for destination in destinations {
        let slot = SenderSlot {
            fragment_instance_id: FragmentInstanceId::from(&destination.fragment_instance_id),
            node_id: stream_sink.dest_node_id,
            sender_id,
        };
        if slots.contains(&slot) {
            return Err(format!(
                "duplicate destination {slot:?} in one data stream sink; two claims would \
                 race over one output stream"
            ));
        }
        let route = self.route_destination(destination)?;
        if let DestinationRoute::Remote { host, brpc_port } = &route
            && self.transport.is_none()
        {
            return Err(format!(
                "cross-node exchange to {host}:{brpc_port} needs the nixl transport \
                 tier, which is not active: build the CN with the `nixl-transport` \
                 feature (default) and set SIRIUS_EXCHANGE_STAGING_BYTES so the \
                 exchange staging arena exists"
            ));
        }
        slots.push(slot);
        routes.push(route);
    }

    // The sender's rows stay on the GPU, parked once with one output stream per
    // destination; only rendezvous bookkeeping and packed exports leave the engine thread.
    self.run_labeled(
        "sender",
        FragmentRun {
            plan: &translated,
            inputs,
            remote_inputs,
            outputs: slots.clone(),
            broadcast,
            hash_keys,
            label: Self::fragment_label(params),
        },
    )?;

    // Local destinations first: their rendezvous is immediate bookkeeping and fails fast.
    let mut ready_receivers = Vec::new();
    for (slot, route) in slots.iter().zip(&routes) {
        if matches!(route, DestinationRoute::Local) {
            let ready = self.exchanges.push_sender(
                ExchangeKey {
                    fragment_instance_id: slot.fragment_instance_id,
                    node_id: slot.node_id,
                },
                sender_id,
                SenderSource::LocalParked {
                    names: translated.output_names.clone(),
                    slot: *slot,
                },
            )?;
            ready_receivers.extend(ready);
        }
    }
    // Remote destinations second: POST each drain and keep its ticket instead of blocking
    // here. The caller dispatches `ready_receivers` first and joins the tickets after, so a
    // local receiver whose sender set this push just completed starts while the transport
    // thread is still draining this CN's remote destinations — measured, that wait was
    // 3 x 30 ms per CN on q14 SF500's 948 MB/destination stage.
    //
    // ORDER IS UNCHANGED, and deliberately so: one FIFO request channel into ONE transport
    // thread that still handles `SendFragment` inline means the drains still run one at a
    // time, in the FE's destination order, with every frame of a destination issued by that
    // single thread. `seq`, eos, and the exactly-once `drop_parked` all stay inside the
    // transport thread's own drain loop, so the receiver's per-(exchange, sender) gap check
    // (local_exchange.rs:180-197) sees exactly the byte sequence it sees today.
    let mut drains = SenderDrains::default();
    for (slot, route) in slots.iter().zip(&routes) {
        if let DestinationRoute::Remote { host, brpc_port } = route {
            let transport = self.transport.as_ref().expect("routed before running");
            let spec = RemoteSendSpec {
                host: host.clone(),
                brpc_port: *brpc_port,
                slot: *slot,
                names: translated.output_names.clone(),
                label: Self::fragment_label(params),
            };
            match transport.start_fragment(spec) {
                Ok(ticket) => drains.push(ticket),
                // Posting failed (the transport is shutting down). Join what is already in
                // flight before unwinding: a ticket dropped un-joined discards a real drain
                // failure, and this is the one path where tickets exist and `?` could fire.
                Err(err) => {
                    let _ = drains.join();
                    return Err(err);
                }
            }
        }
    }
    Ok(FragmentOutcome {
        ready: ready_receivers,
        drains,
    })
}

/// Classifies a data-stream sink destination against this CN's advertised exchange
/// identity. A missing `brpc_server` is a malformed dispatch, not a local default: the FE
/// always attaches the receiver's brpc address (ExecutionDAG.java:560).
fn route_destination(
    &self,
    destination: &TPlanFragmentDestination,
) -> std::result::Result<DestinationRoute, String> {
    let brpc_server = destination.brpc_server.as_ref().ok_or_else(|| {
        format!(
            "DATA_STREAM_SINK destination for fragment instance {} has no brpc_server address",
            FragmentInstanceId::from(&destination.fragment_instance_id)
        )
    })?;
    if self.identity.matches(brpc_server) {
        Ok(DestinationRoute::Local)
    } else {
        Ok(DestinationRoute::Remote {
            host: brpc_server.hostname.clone(),
            brpc_port: u16::try_from(brpc_server.port).map_err(|_| {
                format!(
                    "destination brpc port {} is not a valid TCP port",
                    brpc_server.port
                )
            })?,
        })
    }
}

/// Loads a peer's nixl agent metadata into this CN's agent and returns ours.
fn handle_exchange_nixl_md(
    &self,
    request: &PExchangeNixlMd,
) -> std::result::Result<crate::nixl_transport::MdReply, String> {
    let Some(transport) = self.transport.as_ref() else {
        return Err(
            "the nixl transport tier is not active on this CN: build with the \
             `nixl-transport` feature (default) and set SIRIUS_EXCHANGE_STAGING_BYTES"
                .to_string(),
        );
    };
    let peer_agent_name = request
        .agent_name
        .clone()
        .filter(|name| !name.is_empty())
        .ok_or_else(|| "exchange_nixl_md request carries no agent name".to_string())?;
    let peer_metadata = request
        .agent_metadata
        .clone()
        .filter(|metadata| !metadata.is_empty())
        .ok_or_else(|| "exchange_nixl_md request carries no agent metadata".to_string())?;
    transport.exchange_md(peer_agent_name, peer_metadata)
}

/// Leases `length` bytes of the staging arena and returns `(absolute address, offset)`.
fn handle_staging_lease(&self, length: u64) -> std::result::Result<(u64, u64), String> {
    let (base, _capacity) = self.staging_info()?;
    let offset = self.executor.staging_lease(length)?;
    Ok((base + offset, offset))
}

/// Staging arena `(base, capacity)`, cached after the first successful engine round-trip.
fn staging_info(&self) -> std::result::Result<(u64, u64), String> {
    let mut cached = self
        .staging_info
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if let Some(info) = *cached {
        return Ok(info);
    }
    let info = self.executor.staging_info()?;
    *cached = Some(info);
    Ok(info)
}

/// Translates a receiver whose sender set is complete, binding each exchange to the input
/// stream its senders parked into (or staged, for remote senders), and runs it. Returns the
/// next receiver when this one's own sink completed another sender set.
fn execute_ready_fragment(
    &self,
    ready: ReadyFragment,
) -> std::result::Result<FragmentOutcome, String> {
    let exchange_inputs = ready
        .inputs

        .inputs
        .iter()
        .map(|input| {
            let names = input
                .sources
                .first()
                .map(|source| source.names().to_vec())
                .ok_or_else(|| {
                    format!("exchange node {} has no sender source", input.node_id)
                })?;
            // Local and remote senders alike must agree on the schema they produced; the
            // first source is the reference, disagreement fails the query.
            if input
                .sources
                .iter()
                .any(|source| source.names() != names.as_slice())
            {
                return Err("exchange senders produced different output names".to_string());
            }
            let stream_id = u64::try_from(input.node_id)
                .map_err(|_| format!("negative exchange node id {}", input.node_id))?;
            Ok(ExchangeInput {
                node_id: input.node_id,
                stream_view: sirius_stream_view_name(stream_id),
                names,
            })
        })
        .collect::<Result<Vec<_>, String>>()?;
    // A receiver translates when its sender set completes, not at arrival, so pair its plan
    // dump with a fresh params dump here (the arrival-time dump carried no plan yet).
    let dump_seq = Self::dump_fragment(&ready.params);
    let translated =
        self.translate_fragment_logged_with_inputs(&ready.params, &exchange_inputs, dump_seq)?;
    let mut inputs: Vec<(i32, Vec<SenderSlot>)> = Vec::new();
    let mut remote_inputs: Vec<(i32, i32, Vec<StagedBatch>)> = Vec::new();
    for input in ready.inputs {
        let mut slots = Vec::new();
        for source in input.sources {
            match source {
                SenderSource::LocalParked { slot, .. } => slots.push(slot),
                SenderSource::Remote {
                    sender_id,
                    batches,
                    closed,
                    ..
                } => {
                    // take_ready only releases complete sender sets; an open remote source
                    // here is a rendezvous bug, not a recoverable state.
                    if !closed {
                        return Err(format!(
                            "exchange node {} became ready with remote sender {sender_id} \
                             still open",
                            input.node_id
                        ));
                    }
                    remote_inputs.push((input.node_id, sender_id, batches));
                }
            }
        }
        if !slots.is_empty() {
            inputs.push((input.node_id, slots));
        }
    }
    self.execute_fragment_with_inputs(&ready.params, translated, inputs, remote_inputs)
}

/// Finds every exchange receiver in a fragment and each expected sender count.
fn receiver_exchanges(
    params: &TExecPlanFragmentParams,
) -> std::result::Result<Vec<(i32, usize)>, String> {
    let exchange_nodes = params
        .fragment
        .as_ref()
        .and_then(|fragment| fragment.plan.as_ref())
        .map(|plan| {
            plan.nodes
                .iter()
                .filter(|node| {
                    node.node_type == starrocks_thrift::plan_nodes::TPlanNodeType::EXCHANGE_NODE
                })
                .map(|node| node.node_id)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    exchange_nodes
        .into_iter()
        .map(|node_id| {
            let expected = params
                .params
                .as_ref()
                .and_then(|exec| exec.per_exch_num_senders.get(&node_id))
                .copied()
                .ok_or_else(|| {
                    format!("EXCHANGE_NODE {node_id} is missing per_exch_num_senders")
                })?;
            let expected = usize::try_from(expected).map_err(|_| {
                format!("EXCHANGE_NODE {node_id} has negative sender count {expected}")
            })?;
            Ok((node_id, expected))
        })
        .collect()
}

/// Converts a StarRocks thrift plan fragment to Substrait, logs substrait-explain output, and
/// returns the translated plan for execution.
#[instrument(skip_all)]
fn translate_fragment_logged(
    &self,
    params: &TExecPlanFragmentParams,
    dump_seq: Option<u64>,
) -> std::result::Result<TranslatedPlan, String> {
    self.translate_fragment_logged_with_inputs(params, &[], dump_seq)
}

fn translate_fragment_logged_with_inputs(
    &self,
    params: &TExecPlanFragmentParams,
    exchange_inputs: &[ExchangeInput],
    dump_seq: Option<u64>,
) -> std::result::Result<TranslatedPlan, String> {
    let translated = self
        .translator
        .translate_fragment_with_exchange_inputs(params, exchange_inputs)
        .map_err(|err| err.to_string())?;
    info!(
        output_names = ?translated.output_names,
        plan = %translated.explain(),
        "translated StarRocks plan fragment"
    );
    Self::dump_substrait(&translated, dump_seq);
    Ok(translated)
}

/// Writes the translated Substrait plan bytes to `$SIRIUS_CN_DUMP_FRAGMENTS/plan-<seq>.substrait`
/// so a failing plan can be replayed against the engine in isolation; `<seq>` pairs the plan
/// with its `fragment-<seq>.txt` params dump. No-op when the variable (or the seq) is unset.
fn dump_substrait(translated: &TranslatedPlan, dump_seq: Option<u64>) {
    let Ok(dir) = std::env::var("SIRIUS_CN_DUMP_FRAGMENTS") else {
        return;
    };
    let Some(seq) = dump_seq else {
        return;
    };
    let path = std::path::Path::new(&dir).join(format!("plan-{seq:04}.substrait"));
    if let Err(err) = std::fs::write(&path, translated.to_substrait_bytes()) {
        tracing::warn!(error = %err, path = %path.display(), "failed to dump substrait plan");
    }
}

/// Classifies the fragment output sink: `Ok(true)` for a MySQL text-protocol RESULT_SINK this
/// CN can encode, `Ok(false)` for a non-result sink, and `Err` for a
/// RESULT_SINK whose format is not supported yet (binary rows, HTTP/FILE/Arrow Flight, etc.).
/// The encoder only emits MySQL text rows, so other result-sink formats must be rejected
/// rather than returned in the wrong wire format.
fn is_mysql_result_sink(params: &TExecPlanFragmentParams) -> std::result::Result<bool, String> {
    let Some(sink) = params
        .fragment
        .as_ref()
        .and_then(|fragment| fragment.output_sink.as_ref())
    else {
        return Ok(false);
    };
    if sink.type_ != TDataSinkType::RESULT_SINK {
        return Ok(false);
    }
    // A RESULT_SINK with no nested detail defaults to MySQL text rows.
    let Some(result_sink) = sink.result_sink.as_ref() else {
        return Ok(true);
    };
    if matches!(result_sink.is_binary_row, Some(true)) {
        return Err("binary-row result sinks are not supported yet".to_string());
    }
    match result_sink.type_ {
        None | Some(TResultSinkType::MYSQL_PROTOCAL) => Ok(true),
        Some(other) => Err(format!("result sink type {other:?} is not supported yet")),
    }
}

/// Names a thrift sink type for an operator. The generated type is a newtype over the wire
/// number, so its `Debug` prints `TDataSinkType(7)` — useless in an FE error message.
fn data_sink_type_name(sink_type: TDataSinkType) -> String {
    let name = match sink_type {
        TDataSinkType::DATA_STREAM_SINK => "DATA_STREAM_SINK",
        TDataSinkType::RESULT_SINK => "RESULT_SINK",
        TDataSinkType::DATA_SPLIT_SINK => "DATA_SPLIT_SINK",
        TDataSinkType::MYSQL_TABLE_SINK => "MYSQL_TABLE_SINK",
        TDataSinkType::EXPORT_SINK => "EXPORT_SINK",
        TDataSinkType::OLAP_TABLE_SINK => "OLAP_TABLE_SINK",
        TDataSinkType::MEMORY_SCRATCH_SINK => "MEMORY_SCRATCH_SINK",
        TDataSinkType::MULTI_CAST_DATA_STREAM_SINK => "MULTI_CAST_DATA_STREAM_SINK",
        TDataSinkType::SCHEMA_TABLE_SINK => "SCHEMA_TABLE_SINK",
        TDataSinkType::ICEBERG_TABLE_SINK => "ICEBERG_TABLE_SINK",
        TDataSinkType::HIVE_TABLE_SINK => "HIVE_TABLE_SINK",
        TDataSinkType::TABLE_FUNCTION_TABLE_SINK => "TABLE_FUNCTION_TABLE_SINK",
        TDataSinkType::BLACKHOLE_TABLE_SINK => "BLACKHOLE_TABLE_SINK",
        TDataSinkType::DICTIONARY_CACHE_SINK => "DICTIONARY_CACHE_SINK",
        TDataSinkType::MULTI_OLAP_TABLE_SINK => "MULTI_OLAP_TABLE_SINK",
        TDataSinkType::SPLIT_DATA_STREAM_SINK => "SPLIT_DATA_STREAM_SINK",
        TDataSinkType::NOOP_SINK => "NOOP_SINK",
        TDataSinkType::ICEBERG_DELETE_SINK => "ICEBERG_DELETE_SINK",
        other => return format!("unknown (wire value {})", other.0),
    };
    name.to_string()
}

/// Runs one fragment on the executor, bracketed by this CN's start/finish lines. Those lines
/// carry the StarRocks query id, the fragment instance id, and this CN's exchange endpoint —
/// the same three names the engine's Quent Query label (`<query id>:<fragment instance id>`
/// in the group `<query id>`, engine `<endpoint>`) and the transport's transmit line use — so
/// one query's halves on different CNs can be stitched from logs and telemetry alike.
fn run_labeled(
    &self,
    role: &'static str,
    run: FragmentRun<'_>,
) -> std::result::Result<Option<FragmentResult>, String> {
    let (query_id, fragment_instance_id) = run.label.log_ids();
    let cn = self.identity.endpoint();
    let inputs = run.inputs.len() + run.remote_inputs.len();
    let outputs = run.outputs.len();
    info!(
        %query_id,
        %fragment_instance_id,
        %cn,
        role,
        inputs,
        outputs,
        "fragment run started"
    );
    let started = std::time::Instant::now();
    let result = self.executor.run(run);
    let elapsed_ms = started.elapsed().as_millis() as u64;

//! Sequential exchange rendezvous.
//!
//! The exchange matches StarRocks' receiver-first dispatch with the senders that arrive later.
//! A same-node sender's rows stay on the GPU, parked in the engine as native batches; a remote
//! sender's batches arrive as staged packed bytes in this CN's arena (nixl tier, PLAN-PATH-B B5).
//! Either way, what is tracked here is which senders have finished and where their output sits.

use std::collections::HashMap;
use std::sync::Mutex;

use starrocks_thrift::internal_service::TExecPlanFragmentParams;
use tracing::info;

use crate::fragment_executor::{SenderSlot, StagedBatch};
use crate::result_store::FragmentInstanceId;

/// Receiver identity used by both the stream sink and exchange node.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub(crate) struct ExchangeKey {
    pub(crate) fragment_instance_id: FragmentInstanceId,
    pub(crate) node_id: i32,
}

/// One sender's output, and where it sits.
#[derive(Clone, Debug)]
pub(crate) enum SenderSource {
    /// A same-node sender whose batches the engine parked on the GPU.
    LocalParked {
        /// Sender output names, which become the input stream's column names.
        names: Vec<String>,
        /// Where the engine parked this sender's batches.
        slot: SenderSlot,
    },
    /// A remote sender whose packed batches were nixl-WRITTEN into this CN's staging arena and
    /// announced over `transmit_packed`. Counts toward readiness only once `closed`.
    Remote {
        /// Sender output names carried on every `transmit_packed` frame (first frame wins,
        /// later frames must match).
        names: Vec<String>,
        /// Sender ordinal, needed to `close_input` the engine stream it feeds.
        sender_id: i32,
        /// Batches staged in arrival (sequence) order; the engine releases each lease after
        /// pushing it.
        batches: Vec<StagedBatch>,
        /// The sender announced eos; no more frames may follow.
        closed: bool,
    },
}

impl SenderSource {
    /// The sender's output column names, whichever side of the wire it sits on.
    pub(crate) fn names(&self) -> &[String] {
        match self {
            Self::LocalParked { names, .. } | Self::Remote { names, .. } => names,
        }
    }

    /// Whether this sender has finished producing (a parked local sender always has).
    fn is_complete(&self) -> bool {
        match self {
            Self::LocalParked { .. } => true,
            Self::Remote { closed, .. } => *closed,
        }
    }
}

/// One exchange input of a receiver fragment whose sender set is complete.
#[derive(Debug)]
pub(crate) struct ReadyExchangeInput {
    pub(crate) node_id: i32,
    pub(crate) sources: Vec<SenderSource>,
}

/// A receiver fragment whose exchange inputs are all ready for sequential execution.
#[derive(Debug)]
pub(crate) struct ReadyFragment {
    pub(crate) params: TExecPlanFragmentParams,
    pub(crate) inputs: Vec<ReadyExchangeInput>,
}

#[derive(Debug)]
struct PendingReceiver {
    params: TExecPlanFragmentParams,
    expected_senders: HashMap<i32, usize>,
}

#[derive(Debug, Default)]
struct ExchangeState {
    receivers: HashMap<FragmentInstanceId, PendingReceiver>,
    sources: HashMap<ExchangeKey, HashMap<i32, SenderSource>>,
    /// Next expected `transmit_packed` sequence number per remote sender: a duplicate (below) is
    /// dropped idempotently — brpc reconnect-retry can replay a frame — and a gap (above) is a
    /// lost frame, which must fail the query rather than silently drop rows.
    remote_seq: HashMap<(ExchangeKey, i32), i64>,
}

/// Matches receiver-first StarRocks dispatch with later same-node sender results.
#[derive(Debug, Default)]
pub(crate) struct LocalExchange {
    inner: Mutex<ExchangeState>,
}

impl LocalExchange {
    /// Registers a receiver fragment, returning it when every exchange input is complete.
    pub(crate) fn register_receiver(
        &self,
        fragment_instance_id: FragmentInstanceId,
        expected_senders: Vec<(i32, usize)>,
        params: TExecPlanFragmentParams,
    ) -> Result<Option<ReadyFragment>, String> {
        if expected_senders.is_empty() {
            return Err("receiver fragment has no exchange inputs".to_string());
        }
        let mut expected_by_node = HashMap::with_capacity(expected_senders.len());
        for (node_id, expected) in expected_senders {
            if expected == 0 {
                return Err(format!("exchange node {node_id} expects no senders"));
            }
            if expected_by_node.insert(node_id, expected).is_some() {
                return Err(format!(
                    "duplicate exchange node {node_id} in receiver fragment"
                ));
            }
        }
        let mut state = self.lock();
        if state.receivers.contains_key(&fragment_instance_id) {
            return Err(format!(
                "duplicate receiver registration for fragment {fragment_instance_id}"
            ));
        }
        state.receivers.insert(
            fragment_instance_id,
            PendingReceiver {
                params,
                expected_senders: expected_by_node,
            },
        );
        Self::take_ready(&mut state, fragment_instance_id)
    }

    /// Records one sender as produced, returning the receiver when this completes its sender set.
    pub(crate) fn push_sender(
        &self,
        key: ExchangeKey,
        sender_id: i32,
        source: SenderSource,
    ) -> Result<Option<ReadyFragment>, String> {
        let mut state = self.lock();
        let senders = state.sources.entry(key).or_default();
        if senders.contains_key(&sender_id) {
            return Err(format!("duplicate sender {sender_id} for exchange {key:?}"));
        }
        senders.insert(sender_id, source);
        Self::take_ready(&mut state, key.fragment_instance_id)
    }

    /// Records one `transmit_packed` frame from a remote sender: a staged batch, eos, or both.
    /// Returns the receiver when the eos completes its sender set.
    pub(crate) fn push_remote_frame(
        &self,
        key: ExchangeKey,
        sender_id: i32,
        seq: i64,
        eos: bool,
        names: Vec<String>,
        batch: Option<StagedBatch>,
    ) -> Result<Option<ReadyFragment>, String> {
        if names.is_empty() {
            return Err(format!(
                "remote sender {sender_id} for exchange {key:?} sent a frame without column \
                 names; the receiver cannot bind its input stream schema"
            ));
        }
        if batch.is_none() && !eos {
            return Err(format!(
                "remote sender {sender_id} for exchange {key:?} sent frame seq {seq} carrying \
                 neither a batch nor eos"
            ));
        }
        let mut state = self.lock();

        let expected_seq = state.remote_seq.entry((key, sender_id)).or_insert(0);
        if seq < *expected_seq {
            // brpc reconnect-retry can replay a frame the peer already processed; its batch (if
            // any) landed in the same lease the first delivery recorded, so dropping the replay
            // loses nothing and leaks nothing.
            info!(
                exchange = ?key,
                sender_id, seq, "dropping duplicate remote exchange frame"
            );
            return Ok(None);
        }
        if seq > *expected_seq {
            return Err(format!(
                "remote sender {sender_id} for exchange {key:?} skipped from frame seq \
                 {expected_seq} to {seq}; a frame was lost"
            ));
        }
        *expected_seq += 1;

        let senders = state.sources.entry(key).or_default();
        let source = senders
            .entry(sender_id)
            .or_insert_with(|| SenderSource::Remote {
                names: names.clone(),
                sender_id,
                batches: Vec::new(),
                closed: false,
            });
        let SenderSource::Remote {
            names: known_names,
            batches,
            closed,
            ..
        } = source
        else {
            return Err(format!(
                "remote frame for exchange {key:?} sender {sender_id} collides with a local \
                 parked sender of the same id"
            ));
        };
        if *closed {
            return Err(format!(
                "remote sender {sender_id} for exchange {key:?} sent frame seq {seq} after eos"
            ));
        }
        if known_names != &names {
            return Err(format!(
                "remote sender {sender_id} for exchange {key:?} changed its column names from \
                 {known_names:?} to {names:?}"
            ));
        }
        if let Some(batch) = batch {
            if batch.metadata.is_empty() {
                return Err(format!(
                    "remote sender {sender_id} for exchange {key:?} sent frame seq {seq} with \
                     empty pack metadata"
                ));
            }
            batches.push(batch);
        }
        if eos {
            *closed = true;
        }
        Self::take_ready(&mut state, key.fragment_instance_id)
    }

    fn take_ready(
        state: &mut ExchangeState,
        fragment_instance_id: FragmentInstanceId,
    ) -> Result<Option<ReadyFragment>, String> {
        let Some(receiver) = state.receivers.get(&fragment_instance_id) else {
            return Ok(None);
        };
        for (&node_id, &expected) in &receiver.expected_senders {
            let key = ExchangeKey {
                fragment_instance_id,
                node_id,
            };
            let sources = state.sources.get(&key);
            let total = sources.map(HashMap::len).unwrap_or(0);
            if total > expected {
                return Err(format!(
                    "exchange {key:?} received {total} senders but expected {expected}"
                ));
            }
            // A remote sender counts only once its eos arrived; a local parked one is done by
            // construction.
            let complete = sources
                .map(|senders| {
                    senders
                        .values()
                        .filter(|source| source.is_complete())
                        .count()
                })
                .unwrap_or(0);
            if complete != expected {
                return Ok(None);
            }
        }

        let receiver = state
            .receivers
            .remove(&fragment_instance_id)
            .expect("receiver checked above");
        let mut node_ids = receiver.expected_senders.into_keys().collect::<Vec<_>>();
        node_ids.sort_unstable();
        let inputs = node_ids
            .into_iter()
            .map(|node_id| {
                let key = ExchangeKey {
                    fragment_instance_id,
                    node_id,
                };
                let mut senders = state.sources.remove(&key).unwrap_or_default();
                let mut sender_ids = senders.keys().copied().collect::<Vec<_>>();
                sender_ids.sort_unstable();
                let sources = sender_ids
                    .into_iter()
                    .map(|sender_id| senders.remove(&sender_id).expect("sender id came from map"))
                    .collect();
                ReadyExchangeInput { node_id, sources }
            })
            .collect();
        // The receiver is leaving the rendezvous; drop its remote-sender sequence tracking too.
        state
            .remote_seq
            .retain(|(key, _), _| key.fragment_instance_id != fragment_instance_id);
        Ok(Some(ReadyFragment {
            params: receiver.params,
            inputs,
        }))
    }

    fn lock(&self) -> std::sync::MutexGuard<'_, ExchangeState> {
        self.inner
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }
}

#[cfg(test)]
mod tests {
    use starrocks_thrift::internal_service::InternalServiceVersion;

    use super::*;

    fn key(instance: u64, node_id: i32) -> ExchangeKey {
        ExchangeKey {
            fragment_instance_id: FragmentInstanceId::from_halves(7, instance as i64),

            fragment_instance_id: FragmentInstanceId::from_halves(7, instance as i64),
            node_id,
        }
    }

    /// The rendezvous only stores the params, so an empty shell is enough here.
    fn params() -> TExecPlanFragmentParams {
        TExecPlanFragmentParams {
            protocol_version: InternalServiceVersion::V1,
            fragment: None,
            desc_tbl: None,
            params: None,
            coord: None,
            backend_num: None,
            query_globals: None,
            query_options: None,
            enable_profile: None,
            resource_info: None,
            import_label: None,
            db_name: None,
            load_job_id: None,
            load_error_hub_info: None,
            is_pipeline: None,
            pipeline_dop: None,
            per_scan_node_dop: None,
            workgroup: None,
            enable_resource_group: None,
            func_version: None,
            enable_shared_scan: None,
            is_stream_pipeline: None,
            adaptive_dop_param: None,
            group_execution_scan_dop: None,
            pred_tree_params: None,
            exec_stats_node_ids: None,
            arrow_flight_sql_version: None,
        }
    }

    fn names() -> Vec<String> {
        vec!["id".to_string(), "name".to_string()]
    }

    fn staged(fill: u8) -> StagedBatch {
        StagedBatch {
            metadata: vec![fill; 4],
            offset: u64::from(fill) * 1024,
            len: 512,
            rows: Some(u64::from(fill)),
        }
    }

    fn local_slot(key: ExchangeKey, sender_id: i32) -> SenderSlot {
        SenderSlot {
            fragment_instance_id: key.fragment_instance_id,
            node_id: key.node_id,
            sender_id,
        }
    }

    /// Remote frames accumulate in sequence order; only the eos completes the sender, and the
    /// batches come out in arrival order.
    #[test]
    fn remote_frames_accumulate_and_eos_completes_the_set() {
        let exchange = LocalExchange::default();
        let key = key(1, 7);

        assert!(
            exchange
                .push_remote_frame(key, 0, 0, false, names(), Some(staged(1)))
                .unwrap()
                .is_none()
        );
        assert!(
            exchange
                .push_remote_frame(key, 0, 1, false, names(), Some(staged(2)))
                .unwrap()
                .is_none()
        );
        // The receiver registers mid-stream; still not ready, the sender has not closed.
        assert!(
            exchange
                .register_receiver(key.fragment_instance_id, vec![(7, 1)], params())
                .unwrap()
                .is_none()
        );

        let ready = exchange
            .push_remote_frame(key, 0, 2, true, names(), None)
            .unwrap()
            .expect("eos completes the sender set");
        assert_eq!(ready.inputs.len(), 1);
        assert_eq!(ready.inputs[0].node_id, 7);
        let SenderSource::Remote {
            names: got_names,
            sender_id,
            batches,
            closed,
        } = &ready.inputs[0].sources[0]
        else {
            panic!("expected a remote source");
        };
        assert_eq!(got_names, &names());
        assert_eq!(*sender_id, 0);
        assert!(*closed);
        assert_eq!(batches, &vec![staged(1), staged(2)]);
    }

    /// A replayed frame (brpc reconnect-retry) is dropped idempotently, even after eos.
    #[test]
    fn duplicate_remote_seq_is_dropped_idempotently() {
        let exchange = LocalExchange::default();
        let key = key(2, 7);
        exchange
            .push_remote_frame(key, 0, 0, false, names(), Some(staged(1)))
            .unwrap();
        assert!(
            exchange
                .push_remote_frame(key, 0, 0, false, names(), Some(staged(1)))
                .unwrap()
                .is_none(),
            "replayed data frame is dropped"
        );
        exchange
            .push_remote_frame(key, 0, 1, true, names(), None)
            .unwrap();
        assert!(
            exchange
                .push_remote_frame(key, 0, 1, true, names(), None)
                .unwrap()
                .is_none(),
            "replayed eos frame is dropped"
        );
        // The single staged batch survived, un-duplicated.
        let ready = exchange
            .register_receiver(key.fragment_instance_id, vec![(7, 1)], params())
            .unwrap()
            .expect("sender already complete");
        let SenderSource::Remote { batches, .. } = &ready.inputs[0].sources[0] else {
            panic!("expected a remote source");
        };
        assert_eq!(batches.len(), 1);
    }

    /// A sequence gap means a frame was lost; the query must fail rather than lose rows.
    #[test]
    fn remote_seq_gap_is_a_loud_error() {
        let exchange = LocalExchange::default();
        let key = key(3, 7);
        exchange
            .push_remote_frame(key, 0, 0, false, names(), Some(staged(1)))
            .unwrap();
        let err = exchange
            .push_remote_frame(key, 0, 2, false, names(), Some(staged(2)))
            .unwrap_err();
        assert!(err.contains("skipped from frame seq 1 to 2"), "{err}");
    }

    /// A new frame after eos is a protocol violation, never a silent append.
    #[test]
    fn remote_frame_after_eos_is_a_loud_error() {
        let exchange = LocalExchange::default();
        let key = key(4, 7);
        exchange
            .push_remote_frame(key, 0, 0, true, names(), None)
            .unwrap();
        let err = exchange
            .push_remote_frame(key, 0, 1, false, names(), Some(staged(1)))
            .unwrap_err();
        assert!(err.contains("after eos"), "{err}");
    }

    /// All frames of one sender must agree on the column names.
    #[test]
    fn remote_names_must_match_across_frames() {
        let exchange = LocalExchange::default();
        let key = key(5, 7);
        exchange
            .push_remote_frame(key, 0, 0, false, names(), Some(staged(1)))
            .unwrap();
        let err = exchange
            .push_remote_frame(key, 0, 1, false, vec!["other".to_string()], Some(staged(2)))
            .unwrap_err();
        assert!(err.contains("changed its column names"), "{err}");
    }

    /// Frames must carry names (the receiver binds its stream schema from them) and either a
    /// batch or eos.
    #[test]
    fn remote_frame_shape_is_validated() {
        let exchange = LocalExchange::default();
        let key = key(6, 7);
        let err = exchange
            .push_remote_frame(key, 0, 0, false, Vec::new(), Some(staged(1)))
            .unwrap_err();
        assert!(err.contains("without column names"), "{err}");
        let err = exchange
            .push_remote_frame(key, 0, 0, false, names(), None)
            .unwrap_err();
        assert!(err.contains("neither a batch nor eos"), "{err}");
    }

    /// A fan-in of one local parked sender and one remote sender becomes ready only when the
    /// local sender has parked AND the remote sender has closed.
    #[test]
    fn mixed_local_and_remote_sender_set() {
        let exchange = LocalExchange::default();
        let key = key(8, 7);
        assert!(
            exchange
                .register_receiver(key.fragment_instance_id, vec![(7, 2)], params())
                .unwrap()
                .is_none()
        );
        assert!(
            exchange
                .push_sender(
                    key,
                    0,
                    SenderSource::LocalParked {
                        names: names(),
                        slot: local_slot(key, 0),
                    },
                )
                .unwrap()
                .is_none()
        );
        assert!(
            exchange
                .push_remote_frame(key, 1, 0, false, names(), Some(staged(3)))
                .unwrap()
                .is_none(),
            "an open remote sender must not count as complete"
        );
        let ready = exchange
            .push_remote_frame(key, 1, 1, true, names(), None)
            .unwrap()
            .expect("both senders now complete");
        assert_eq!(ready.inputs[0].sources.len(), 2);
        assert!(matches!(
            ready.inputs[0].sources[0],
            SenderSource::LocalParked { .. }
        ));
        assert!(matches!(
            ready.inputs[0].sources[1],
            SenderSource::Remote { sender_id: 1, .. }
        ));
    }

    /// A remote frame colliding with an already-parked local sender of the same id is a bug in
    /// the sender set, reported loudly.
    #[test]
    fn remote_frame_colliding_with_local_sender_is_an_error() {
        let exchange = LocalExchange::default();
        let key = key(9, 7);
        exchange
            .push_sender(
                key,
                0,
                SenderSource::LocalParked {
                    names: names(),
                    slot: local_slot(key, 0),
                },
            )
            .unwrap();
        let err = exchange
            .push_remote_frame(key, 0, 0, false, names(), Some(staged(1)))
            .unwrap_err();
        assert!(err.contains("collides with a local parked sender"), "{err}");
    }
}

use arrow_array::RecordBatch;
use sirius::SiriusContext;
use starrocks_plan_translator::StreamInputSchema;
use tracing::{info, warn};

use crate::engine_settings::EngineSettings;
use crate::fragment_executor::{
    FragmentExecutor, FragmentLabel, FragmentResult, FragmentRun, PinTableSpec, SenderSlot,
    StagedBatch,
};

/// A sender fragment's parked output, shared by its destinations: stream i belongs to
/// destination i. `outstanding` counts destinations that have not yet released their stream
/// (drained + dropped); the fragment -- and its GPU batches -- drop when it reaches zero.
struct ParkedOutput<'ctx> {
    fragment: sirius::Fragment<'ctx>,
    outstanding: usize,
}

/// One fragment execution handed to the engine thread.
///
/// Owned data only: the `sirius::Fragment`s themselves never leave that thread, so what crosses
/// the channel is the plan, the schema of each declared stream, and the slots naming which parked
/// sender outputs to relay in.
struct ExecuteRequest {
    /// Serialized Substrait plan bytes.
    plan: Vec<u8>,
    /// Schema of every exchange this plan reads as a stream.
    stream_inputs: Vec<StreamInputSchema>,
    /// Parked sender outputs to relay in, keyed by receiver exchange node id.
    inputs: Vec<(i32, Vec<SenderSlot>)>,
    /// Remote sender batches staged in this CN's arena, as `(node id, sender id, batches)`:
    /// pushed via `push_packed` + `close_input` before `run()`, each lease released the moment
    /// its push returns (copy-out-on-arrival makes that safe).
    remote_inputs: Vec<(i32, i32, Vec<StagedBatch>)>,
    /// Non-empty for a sender fragment: park once, output stream i belongs to `outputs[i]`.
    outputs: Vec<SenderSlot>,
    /// Every destination receives the full output (broadcast sink).
    broadcast: bool,
    /// Hash-partition key columns for a hash fan-out (empty otherwise).
    hash_keys: Vec<usize>,
    /// Telemetry identity: the engine's Quent Query label and this thread's log span.
    label: FragmentLabel,
    /// Channel the engine thread sends the result (or a flattened error) back on.
    respond: Sender<Result<Option<FragmentResult>, String>>,
}

/// One message to the engine thread — the only caller of `SiriusContext`, which is `!Send`.
/// Every variant carries its own respond channel, so callers block for exactly their answer.
///
/// Staging lease/release/info are deliberately NOT variants here: they are served from the
/// thread-safe arena handle on the caller's thread (see the module doc), because a request
/// queued here waits for whatever fragment the engine thread is running.
enum EngineRequest {
    /// Run one fragment (the original request shape).
    Run(ExecuteRequest),
    /// Test-only: occupy the engine thread for the duration — a stand-in for a long (or
    /// wedged) fragment run, so a test can prove staging leases do not queue behind it.
    #[cfg(test)]
    Sleep(std::time::Duration),
    /// Pack the next batch parked under `slot` into a fresh staging lease (`None` when drained).
    ExportNext {
        slot: SenderSlot,
        respond: Sender<Result<Option<StagedBatch>, String>>,
    },
    /// Drop the parked fragment under `slot` (after its output was transmitted, or on a failed
    /// transmit so the GPU memory is not pinned by a dead query).
    DropParked {
        slot: SenderSlot,
        respond: Sender<Result<(), String>>,
    },
    /// Pin a table into the engine's scan cache (driven by `ADMIN EXECUTE ON <id> '<script>'`).
    /// Deliberately funneled through this channel: pinning mutates the scan registry inside its
    /// own execution window, so it must serialize with fragment runs — the staging-arena bypass
    /// precedent does not apply. A pin queued behind a wedged fragment waits; a long pin makes
    /// queries queue behind it. Pin before running load.
    PinTable {
        spec: PinTableSpec,
        respond: Sender<Result<String, String>>,
    },
    /// Remove a pinned entry by name, releasing its memory.
    UnpinTable {
        name: String,
        respond: Sender<Result<String, String>>,
    },
}

/// GPU-backed [`FragmentExecutor`] running plans on an embedded Sirius engine.
///
/// The engine context lives on a dedicated thread; this handle forwards plans to it and waits for
/// the result. Dropping it closes the request channel, which ends the thread and tears the context
/// down (joined for an ordered teardown).
#[derive(Debug)]
pub struct SiriusEngine {
    /// Sender to the engine thread. `Mutex<Option<..>>` makes the `!Sync` sender shareable and
    /// lets `Drop` close the channel before joining; sends are brief (the thread serializes work).
    requests: Mutex<Option<Sender<EngineRequest>>>,
    /// Engine thread handle, taken and joined on drop.
    thread: Mutex<Option<JoinHandle<()>>>,
    /// Thread-safe staging-arena handle (`None` when `SIRIUS_EXCHANGE_STAGING_BYTES` is unset),
    /// serving every `staging_*` call directly on the caller's thread.
====
        }
        Err(err) => {
            let _ = ready.send(Err(err));
            return;
        }
    };

    // Sender fragments whose output is parked on the GPU, waiting for their receivers to be
    // dispatched. Parked ONCE per fragment; `parked_slots` maps each destination's SenderSlot to
    // (park id, its output stream). Declared after `context` so the fragments drop *first*: a
    // fragment borrows the engine it runs on, and the borrow checker enforces the order the C++
    // side depends on.
    let mut parked: HashMap<u64, ParkedOutput<'_>> = HashMap::new();
    let mut parked_slots: HashMap<SenderSlot, (u64, u64)> = HashMap::new();
    let mut next_park_id: u64 = 0;
    // Why a slot's parked output went away, for the slots the blanket wipe below destroys.
    // Without this the wipe is silent and the NEXT export of an unrelated slot reports
    // "no parked sender output", which is collateral -- it masks the error that actually killed
    // the query. MEASURED: TPC-H q08 reported that error for weeks while the real failure was an
    // OOM in HASH_JOIN. Bounded: an entry is dropped as soon as the slot is parked again.
    let mut poisoned: HashMap<SenderSlot, String> = HashMap::new();

    info!("sirius-engine thread ready");
    // One request at a time until the handle (and its sender) is dropped. Every respond-send
    // error is ignored: the waiting caller may have been dropped/cancelled.
    while let Ok(request) = requests.recv() {
        match request {
            EngineRequest::Run(request) => {
                let result = run_fragment(
                    &context,
                    &mut parked,
                    &mut parked_slots,
                    &poisoned,
                    &mut next_park_id,
                    &request,
                );
                if let Err(err) = &result {
                    // A failed query leaves its parked senders unreachable — the receiver that
                    // would have consumed them is the thing that just failed. Dropping them
                    // releases the GPU memory their batches hold rather than leaking it for the
                    // process's lifetime.
                    //
                    // The wipe is process-wide, so it also destroys OTHER in-flight fragments'
                    // parked output. Record why, and say so out loud: a drain that fails right
                    // after this used to report only "no parked sender output", which names the
                    // victim and hides the culprit.
                    if !parked_slots.is_empty() {
                        warn!(
                            slots = parked_slots.len(),
                            error = %err,
                            "discarding every parked sender output on this CN after a fragment failure"
                        );
                    }
                    // Replace, never accumulate: only the most recent wipe can explain a slot
                    // that is missing now, and this bounds the map by the live slot count.
                    poisoned.clear();
                    for slot in parked_slots.keys() {
                        poisoned.insert(slot.clone(), err.clone());
                    }
                    parked.clear();
                    parked_slots.clear();
                }
                let _ = request.respond.send(result);
            }
            #[cfg(test)]
            EngineRequest::Sleep(duration) => std::thread::sleep(duration),
            EngineRequest::ExportNext { slot, respond } => {
                let result = export_next(&mut parked, &parked_slots, &poisoned, slot);
                let _ = respond.send(result);
            }
            EngineRequest::DropParked { slot, respond } => {
                let result = release_slot(&mut parked, &mut parked_slots, &poisoned, &slot);
                let _ = respond.send(result);
            }
            EngineRequest::PinTable { spec, respond } => {
                info!(name = %spec.name, tier = spec.tier.as_str(), "pin_table starting");

fn run_fragment_inner<'ctx>(
    context: &'ctx SiriusContext,
    parked: &mut HashMap<u64, ParkedOutput<'ctx>>,
    parked_slots: &mut HashMap<SenderSlot, (u64, u64)>,
    poisoned: &HashMap<SenderSlot, String>,
    next_park_id: &mut u64,
    request: &ExecuteRequest,
    released: &mut std::collections::HashSet<u64>,
) -> Result<Option<FragmentResult>, String> {
    let mut fragment = context
        .fragment()
        .map_err(|err| format!("failed to create fragment: {err}"))?;

    // Name the engine's Quent Query after the StarRocks ids before build() opens it, so the
    // telemetry of this fragment and of its peers on other CNs share one query group.
    if let Some(query_label) = request.label.query_label() {
        let session_label = request.label.session_label().unwrap_or_default();
        fragment
            .set_query_label(&query_label, &session_label)
            .map_err(|err| format!("failed to label fragment {query_label}: {err}"))?;
    }

    for schema in &request.stream_inputs {
        let stream_id = stream_id_of(schema.node_id)?;
        for column in &schema.columns {
            fragment
                .declare_input_column(stream_id, &column.name, &column.ty)
                .map_err(|err| {
                    format!(
                        "failed to declare column {} of stream {stream_id}: {err}",
                        column.name
                    )
                })?;
        }
        let senders = request
            .inputs
            .iter()
            .find(|(node_id, _)| *node_id == schema.node_id)
            .map(|(_, senders)| senders.as_slice())
            .unwrap_or_default();
        let remote_senders = request
            .remote_inputs
            .iter()
            .filter(|(node_id, _, _)| *node_id == schema.node_id)
            .map(|(_, sender_id, _)| *sender_id)
            .collect::<Vec<_>>();
        if senders.is_empty() && remote_senders.is_empty() {
            return Err(format!(
                "exchange node {} is read as a stream but no sender output — parked or remote — \
                 exists for it",
                schema.node_id
            ));
        }
        for sender_id in senders
            .iter()
            .map(|slot| slot.sender_id)
            .chain(remote_senders)
        {
            let sender_id =
                u32::try_from(sender_id).map_err(|_| format!("negative sender id {sender_id}"))?;
            fragment
                .declare_input_sender(stream_id, sender_id)
                .map_err(|err| format!("failed to declare sender on stream {stream_id}: {err}"))?;
        }

        // The CN already holds every input of this fragment — parked local sender outputs and
        // staged remote batches — so it can declare the stream's EXACT row count and let
        // DuckDB's optimizer size join order / build-side selection (a stream source binds with
        // no rows behind it, so undeclared streams all estimate cardinality 1: the q07 2-CN
        // regression built its hash join on a multi-GB stream while a 2-row stream probed).
        // Best-effort by design: when any contributor's count is unknown (a spilled parked
        // batch, a remote frame that predates the wire's `rows` field), skip the declaration
        // and keep the legacy blind planning for this stream rather than failing the fragment.
        let local_rows: Option<u64> = senders
            .iter()
            .map(|slot| {
                let (park_id, sender_stream) = parked_slots.get(slot).copied()?;
                let entry = parked.get(&park_id)?;
                entry.fragment.output_row_count(sender_stream).ok()
            })
            .sum();
        let remote_rows: Option<u64> = request
            .remote_inputs
            .iter()
            .filter(|(node_id, _, _)| *node_id == schema.node_id)
            .flat_map(|(_, _, batches)| batches.iter().map(|batch| batch.rows))
            .sum();
        match (local_rows, remote_rows) {
            (Some(local), Some(remote)) => {
                let rows = local + remote;
                fragment
                    .declare_input_cardinality(stream_id, rows)
                    .map_err(|err| {
                        format!("failed to declare cardinality of stream {stream_id}: {err}")
                    })?;
                info!(stream_id, rows, "declared input stream cardinality");
            }
            _ => warn!(
                stream_id,
                "input stream row count unknown; planning without a declared cardinality"
            ),
        }
    }

    // An intermediate fragment sinks into one output stream per destination (stream i belongs
    // to destination outputs[i]); a result fragment declares none and produces Arrow instead.
    for stream in 0..request.outputs.len() as u64 {
        fragment
            .declare_output(stream)
            .map_err(|err| format!("failed to declare fragment output stream {stream}: {err}"))?;
    }
    if request.broadcast && request.outputs.len() > 1 {
        fragment
            .declare_output_broadcast()
            .map_err(|err| format!("failed to declare the broadcast output mode: {err}"))?;
    } else if !request.hash_keys.is_empty() && request.outputs.len() > 1 {
        for &key in &request.hash_keys {
            let key = u32::try_from(key).map_err(|_| format!("hash key column {key} overflows"))?;
            fragment
                .declare_output_hash_key(key)
                .map_err(|err| format!("failed to declare hash key column {key}: {err}"))?;
        }
    }

    fragment
        .build(&request.plan)
        .map_err(|err| format!("failed to plan fragment: {err}"))?;

    // The fragment boundary itself: each sender's batches move into this fragment's input stream
    // as native handles. Nothing is converted, written, or copied.
    for schema in &request.stream_inputs {
        let stream_id = stream_id_of(schema.node_id)?;
        let senders = request
            .inputs
            .iter()
            .find(|(node_id, _)| *node_id == schema.node_id)
            .map(|(_, senders)| senders.as_slice())
            .unwrap_or_default();
        for slot in senders {
            let (park_id, sender_stream) = parked_slots
                .get(slot)
                .copied()
                .ok_or_else(|| format!("no parked sender output for {slot:?}"))?;
            let sender = parked
                .get_mut(&park_id)
                .ok_or_else(|| format!("parked fragment vanished under {slot:?}"))?;
            let sender_id = u32::try_from(slot.sender_id)
                .map_err(|_| format!("negative sender id {}", slot.sender_id))?;
            let moved = fragment
                .relay_from(&mut sender.fragment, sender_stream, stream_id, sender_id)
                .map_err(|err| format!("failed to relay sender {sender_id}: {err}"))?;
            // This destination's stream is drained; release its claim (the fragment drops with
            // the last claim, freeing the GPU batches).
            release_slot(parked, parked_slots, poisoned, slot)?;
            info!(
                stream_id,
                sender_id,
                batches = moved,
                "relayed native batches across a fragment boundary"
            );
        }
    }

    // Remote senders: their packed batches already sit in this CN's staging arena. Push each
    // (deep copy into pool memory), release its lease immediately — copy-out-on-arrival makes
    // that safe — then close the sender.
    for (node_id, sender_id, batches) in &request.remote_inputs {
        let stream_id = stream_id_of(*node_id)?;
        let sender = u32::try_from(*sender_id)
            .map_err(|_| format!("negative remote sender id {sender_id}"))?;
        for batch in batches {
            let staged = sirius::PackedBatch {
                metadata: batch.metadata.clone(),
                offset: batch.offset,
                len: batch.len,
                // push_packed never reads the count; the receiver consumed it before build()
                // through declare_input_cardinality.
                rows: batch.rows.unwrap_or(0),
            };
            fragment.push_packed(stream_id, &staged).map_err(|err| {
                format!(
                    "failed to push a staged remote batch from sender {sender_id} into stream \
                     {stream_id}: {err}"
                )
            })?;
            if batch.len > 0 {
                context.staging_release(batch.offset).map_err(|err| {
                    format!(
                        "failed to release the staging lease at offset {} after pushing it: {err}",
                        batch.offset
                    )
                })?;
                released.insert(batch.offset);
            }
        }
        fragment.close_input(stream_id, sender).map_err(|err| {
            format!("failed to close remote sender {sender_id} on stream {stream_id}: {err}")
        })?;
        info!(
            stream_id,
            sender_id,
            batches = batches.len(),
            bytes = batches.iter().map(|batch| batch.len).sum::<u64>(),
            "received remote batches"
        );
    }

    fragment
        .run()
        .map_err(|err| format!("failed to execute fragment: {err}"))?;

    if !request.outputs.is_empty() {
        // Park ONCE; each destination claims (park id, its stream). A duplicate slot would let
        // two claims race over one stream -- refuse before inserting anything.
        let park_id = *next_park_id;
        *next_park_id += 1;
        for (stream, slot) in request.outputs.iter().enumerate() {
            if parked_slots.contains_key(slot) {
                return Err(format!(
                    "duplicate destination slot {slot:?} in one sender fan-out"
                ));
            }
            parked_slots.insert(slot.clone(), (park_id, stream as u64));
        }
        parked.insert(
            park_id,
            ParkedOutput {
                fragment,
                outstanding: request.outputs.len(),
            },
        );
        return Ok(None);
    }
    {
        // `into_arrow` drains the stream and drops the context-referencing wrapper here, on the
        // engine thread, returning owned batches whose buffers are released via their own Arrow C
        // release callbacks — independent of the context. So they are safe to send to, and drop
        // on, the caller's thread.
        fragment
            .into_arrow()
            .map(|result| Some(FragmentResult::new(result.batches)))
            .map_err(|err| err.to_string())
    }
}

        });
    }
    let child = children.into_iter().next().unwrap();
    translate_project_node(child, node, ctx)
}

/// Translates a flat preorder StarRocks plan into a Substrait relation tree.
///
/// `root_output_exprs` are the fragment's output expressions (empty when absent); they count
/// as consumers sitting above the fragment root for [`common_slots_consumed_above`].
pub(crate) fn translate_plan(
    plan: &TPlan,
    root_output_exprs: &[TExpr],
    desc: &DescriptorTable,
    scan_paths: &ScanFilePaths,
    exchange_inputs: &std::collections::HashMap<i32, &ExchangeInput>,
    registry: &mut ExtensionRegistry,
) -> Result<TranslatedFragment> {
    let mut ctx = PlanContext::new(desc, scan_paths, exchange_inputs, registry);
    ctx.exchange_state_overrides = merge_exchange_overrides(plan)?;
    ctx.consumed_above = common_slots_consumed_above(plan, root_output_exprs, desc)?;
    let root = plan.translate(&mut ctx)?;
    if let Some(expansion) = &ctx.partial_expansion {
        // Only the fragment root's row leaves this CN by name. Any node above the expanded
        // aggregation would resolve the aggregation's slots at their FE positions, which the
        // expansion moved -- a wrong column read, not a type error the engine would catch.
        if plan.nodes.first().map(|node| node.node_id) != Some(expansion.node_id) {
            return Err(TranslateError::UnsupportedPlanNode {
                node_id: expansion.node_id,
                node_type: TPlanNodeType::AGGREGATION_NODE,
                reason: "a partial aggregation over avg must be the fragment root; a node above \
                         it reads the aggregate's columns at the positions the avg state moved \
                         (SET new_planner_agg_stage = 1)",
            });
        }
        if root.output_width != expansion.names.len() {
            return Err(TranslateError::malformed(format!(
                "partial aggregation emits {} columns but named {} of them",
                root.output_width,
                expansion.names.len()
            )));
        }
    }
    Ok(TranslatedFragment {
        root,
        stream_inputs: std::mem::take(&mut ctx.stream_inputs),
        partial_expansion: ctx.partial_expansion,
    })
}

/// Computes the positional wire-column overrides for exchanges that feed merge aggregations.
///
/// Runs over the flat preorder node list before translation, because the exchange is
/// translated before its parent aggregation and must already declare the stream with the
/// modeled partial-state columns — their types, and the extra column a wider state (avg)
/// occupies. In preorder a merge aggregation's single child is simply the next node; anything
/// but an exchange there means the plan reads partial states from a shape this translator
/// cannot type, so it is refused.
fn merge_exchange_overrides(
    plan: &TPlan,
) -> Result<std::collections::HashMap<i32, Vec<StateColumns>>> {
    let mut overrides = std::collections::HashMap::new();
    for (index, node) in plan.nodes.iter().enumerate() {
        if node.node_type != TPlanNodeType::AGGREGATION_NODE {
            continue;
        }
        // A node without agg_node fails in translate_aggregation with its own error.
        let Some(agg) = node.agg_node.as_ref() else {
            continue;
        };
        if agg_phase::classify(node.node_id, node.node_type, agg)? != AggPhase::Merge {
            continue;
        }
        let child = plan
            .nodes
            .get(index + 1)
            .filter(|child| child.node_type == TPlanNodeType::EXCHANGE_NODE);
        if child.is_none() {
            return Err(TranslateError::UnsupportedPlanNode {
                node_id: node.node_id,
                node_type: node.node_type,
                reason: "a merge aggregation must read its partial states directly from an \
                         exchange (SET new_planner_agg_stage = 1)",
            });
        }
        let keys = agg.grouping_exprs.as_deref().unwrap_or_default().len();
        let mut columns = Vec::with_capacity(agg.aggregate_functions.len());
        for (position, measure) in agg.aggregate_functions.iter().enumerate() {
            // The exchange row is the intermediate tuple's materialized slots: grouping keys
            // first, then one state slot per measure -- the same layout invariant the
            // aggregation's output tuple uses. A state wider than its slot (avg) claims the
            // columns behind it, which is where the partial fragment emitted them.
            columns.push(StateColumns {
                position: keys + position,
                types: partial_state::wire_columns(measure_function(measure)?)?
                    .into_iter()
                    .map(|column| column.ty)
                    .collect(),
            });
        }
        overrides.insert(child.unwrap().node_id, columns);
    }
    Ok(overrides)
}

/// Finds, for every project node, the common-expr slots an ancestor consumes even though no
/// output tuple materializes them.
///
/// StarRocks' BE physically outputs a project's common slots when a node above references
/// them, and the FE plans against that; this pre-pass reproduces the FE's view so
/// [`translate_project_node`] can widen the project with the consumed columns. One walk over
/// the flat preorder node list, keeping the open ancestors on a stack (the same span math
/// `PlanNodeCursor` uses): when a `PROJECT_NODE` with a non-empty `common_slot_map` is
/// visited, every expression payload of its strict ancestors — plus `root_output_exprs`,
/// which sit above the fragment root — is scanned for references to its non-materialized
/// common slots. Matching is by slot id alone: new-optimizer slot ids are query-global and an
/// ancestor ref can carry a stale tuple id (see `DescriptorTable::slot_global_index`). A
/// false positive only widens the row with a column the root confinement drops; a false
/// negative leaves today's loud zero-candidate descriptor error. Neither is silent.
fn common_slots_consumed_above(
    plan: &TPlan,
    root_output_exprs: &[TExpr],
    desc: &DescriptorTable,
) -> Result<std::collections::HashMap<i32, Vec<i32>>> {
    let mut consumed = std::collections::HashMap::new();
    // Open ancestors of the node being visited: (node index, children not yet completed).
    let mut stack: Vec<(usize, i32)> = Vec::new();
    for (index, node) in plan.nodes.iter().enumerate() {
        if node.node_type == TPlanNodeType::PROJECT_NODE
            && let Some(common) = node
                .project_node
                .as_ref()
                .and_then(|project| project.common_slot_map.as_ref())
                .filter(|common| !common.is_empty())
        {
            let mut candidates = std::collections::BTreeSet::new();
            for &slot_id in common.keys() {
                let mut materialized = false;
                for &tuple_id in &node.row_tuples {
                    if desc.materialized_slot_ids(tuple_id)?.contains(&slot_id) {
                        materialized = true;
                        break;
                    }
                }
                if !materialized {
                    candidates.insert(slot_id);
                }
            }
            if !candidates.is_empty() {
                let mut hits = std::collections::BTreeSet::new();
                for &(ancestor, _) in &stack {
                    collect_slot_ref_hits(&plan.nodes[ancestor], &candidates, &mut hits);
                }
                for expr in root_output_exprs {
                    collect_expr_slot_ref_hits(expr, &candidates, &mut hits);
                }
                if !hits.is_empty() {
                    consumed.insert(node.node_id, hits.into_iter().collect());
                }
            }
        }
        if node.num_children > 0 {
            stack.push((index, node.num_children));
        } else {
            // A leaf completes itself, and possibly the subtrees of the ancestors above it.
            while let Some(top) = stack.last_mut() {
                top.1 -= 1;
                if top.1 == 0 {
                    stack.pop();
                } else {
                    break;
                }
            }
        }
    }
    Ok(consumed)
}

/// Adds to `hits` every candidate slot id referenced by any expression payload of `node`.
fn collect_slot_ref_hits(
    node: &TPlanNode,

    node: &TPlanNode,
    candidates: &std::collections::BTreeSet<i32>,
    hits: &mut std::collections::BTreeSet<i32>,
) {
    let mut exprs: Vec<&TExpr> = Vec::new();
    exprs.extend(node.conjuncts.as_deref().unwrap_or_default());
    if let Some(agg) = node.agg_node.as_ref() {
        exprs.extend(agg.grouping_exprs.as_deref().unwrap_or_default());
        exprs.extend(&agg.aggregate_functions);
    }
    if let Some(sort) = node.sort_node.as_ref() {
        exprs.extend(&sort.sort_info.ordering_exprs);
        exprs.extend(
            sort.sort_info
                .sort_tuple_slot_exprs
                .as_deref()
                .unwrap_or_default(),
        );
        // Deprecated node-level duplicate some senders populate instead (see translate_sort).
        exprs.extend(sort.sort_tuple_slot_exprs.as_deref().unwrap_or_default());
    }
    if let Some(join) = node.hash_join_node.as_ref() {
        for eq in &join.eq_join_conjuncts {
            exprs.push(&eq.left);
            exprs.push(&eq.right);
        }
        exprs.extend(join.other_join_conjuncts.as_deref().unwrap_or_default());
    }
    if let Some(join) = node.nestloop_join_node.as_ref() {
        exprs.extend(join.join_conjuncts.as_deref().unwrap_or_default());
    }
    if let Some(project) = node.project_node.as_ref() {
        exprs.extend(
            project
                .slot_map
                .as_ref()
                .into_iter()
                .flatten()
                .map(|(_, expr)| expr),
        );
        exprs.extend(
            project
                .common_slot_map
                .as_ref()
                .into_iter()
                .flatten()
                .map(|(_, expr)| expr),
        );
    }
    for expr in exprs {
        collect_expr_slot_ref_hits(expr, candidates, hits);
    }
}

/// Adds to `hits` every candidate slot id one flat preorder expression references.
fn collect_expr_slot_ref_hits(
    expr: &TExpr,
    candidates: &std::collections::BTreeSet<i32>,
    hits: &mut std::collections::BTreeSet<i32>,
) {
    for node in &expr.nodes {
        if node.node_type == starrocks_thrift::exprs::TExprNodeType::SLOT_REF
            && let Some(slot_ref) = node.slot_ref.as_ref()
            && candidates.contains(&slot_ref.slot_id)
        {
            hits.insert(slot_ref.slot_id);
        }
    }
}

/// Replaces a receiver exchange boundary with a read of the sender's output **stream**.
///
/// The sender's rows are already on the GPU, parked in the engine as native batches. So the read
/// resolves to the engine's stream view rather than to a file: nothing is materialized, nothing
/// is re-parsed, and the boundary costs a pointer move. The schema the read declares is also
/// recorded on the context, because the engine has no file to infer it from and the fragment must
/// declare the same one.
fn translate_exchange(
    node: &TPlanNode,
    children: Vec<TranslatedRel>,
    ctx: &mut PlanContext<'_>,
) -> Result<TranslatedRel> {
    expect_children(node, &children, 0)?;
    let exchange = node
        .exchange_node
        .as_ref()
        .ok_or(TranslateError::MissingField {
            context: "EXCHANGE_NODE",
            field: "exchange_node",
        })?;
    if exchange.input_row_tuples.is_empty() {
        return Err(TranslateError::MissingField {
            context: "TExchangeNode",
            field: "input_row_tuples",
        });
    }
    let input =
        ctx.exchange_inputs
            .get(&node.node_id)
            .ok_or(TranslateError::UnsupportedPlanNode {
                node_id: node.node_id,
                node_type: node.node_type,
                reason: "exchange node requires a bound same-node input stream",
            })?;
    let mut schema = ctx
        .desc
        .named_struct_for_tuples(&exchange.input_row_tuples)?;
    // An exchange feeding a merge aggregation carries partial-state columns; rewrite their
    // FE-declared slot types to the modeled wire types, and make room for the states the FE
    // declares in fewer columns than Sirius ships (avg). One `Type`, two consumers: the
    // ReadRel base_schema below and the engine's stream declaration derive from the same
    // rewritten entry, so the plan's view of the column and the engine's cannot drift apart.
    if let Some(state_overrides) = ctx.exchange_state_overrides.get(&node.node_id) {
        let types = schema
            .r#struct
            .as_mut()
            .map(|structure| &mut structure.types)
            .ok_or_else(|| TranslateError::malformed("exchange schema has no struct"))?;
        let width = types.len();
        // Positions index the FE-declared row, so every insertion shifts the ones after it.
        let mut inserted = 0usize;
        for column in state_overrides {
            let position = column.position + inserted;
            let slot = types.get_mut(position).ok_or_else(|| {
                TranslateError::malformed(format!(
                    "merge aggregation state column {} is outside the exchange row \
                     ({width} columns)",
                    column.position
                ))
            })?;
            *slot = column.types[0].clone();
            for (offset, ty) in column.types.iter().enumerate().skip(1) {
                types.insert(position + offset, ty.clone());
            }
            inserted += column.types.len() - 1;
        }
    }
    let output_width = schema
        .r#struct
        .as_ref()
        .map(|structure| structure.types.len())
        .unwrap_or(0);
    // The stream's columns are the sender's, named by the sender: an expanded state has more
    // columns than the receiver's tuple has slots, so the descriptor names cannot name them.
    if input.names.len() != output_width {
        return Err(TranslateError::descriptor(format!(
            "row layout {:?} has {} fields but exchange input has {} names",
            exchange.input_row_tuples,
            output_width,
            input.names.len()
        )));
    }
    schema.names = input.names.clone();

    let columns = schema
        .names
        .iter()
        .cloned()
        .zip(
            schema
                .r#struct
                .as_ref()
                .map(|structure| structure.types.as_slice())
                .unwrap_or_default(),
        )
        .map(|(name, ty)| {
            Ok(StreamInputColumn {
                name,
                ty: crate::type_mapper::duckdb_type_name(ty)?,
            })
        })
        .collect::<Result<Vec<_>>>()?;
    ctx.stream_inputs.push(StreamInputSchema {
        node_id: node.node_id,
        stream_view: input.stream_view.clone(),
        columns,
    });

    let mut translated = TranslatedRel {
        rel: stream_read_rel(schema, &input.stream_view),
        row_tuples: exchange.input_row_tuples.clone(),
        output_width,
        // Streams never carry: the sender's root narrowed any carried columns away, and the
        // declared stream schema describes exactly the descriptor row.
        carried_slots: Vec::new(),
    };
    if let Some(sort_info) = &exchange.sort_info {
        let sorts = sort_fields(sort_info, &translated, ctx)?;
        let row_tuples = translated.row_tuples.clone();
        translated = TranslatedRel {
            rel: Rel {
                rel_type: Some(rel::RelType::Sort(Box::new(SortRel {
                    input: Some(Box::new(translated.rel)),
                    sorts,
                    ..Default::default()
                }))),
            },
            row_tuples,
            output_width,
            carried_slots: Vec::new(),
        };

                .expr_context(&input.row_tuples)
                .with_carried(&input.carried_slots);
            let expr = expr.translate(&mut expr_ctx)?;
            let direction = match (asc, nulls_first) {
                (true, true) => sort_field::SortDirection::AscNullsFirst,
                (true, false) => sort_field::SortDirection::AscNullsLast,
                (false, true) => sort_field::SortDirection::DescNullsFirst,
                (false, false) => sort_field::SortDirection::DescNullsLast,
            };
            Ok(SortField {
                expr: Some(expr),
                sort_kind: Some(sort_field::SortKind::Direction(direction as i32)),
            })
        })
        .collect()
}

/// Translates a `HASH_JOIN_NODE` into a Substrait join relation.
///
/// StarRocks children are `[probe (left), build (right)]`; the Substrait join condition is
/// evaluated over the concatenated left-then-right row, which is exactly how
/// `slot_global_index` resolves slots against the combined layout.
fn translate_hash_join(
    node: &TPlanNode,
    children: Vec<TranslatedRel>,
    ctx: &mut PlanContext<'_>,
) -> Result<TranslatedRel> {
    expect_children(node, &children, 2)?;
    let join = node
        .hash_join_node
        .as_ref()
        .ok_or(TranslateError::MissingField {
            context: "HASH_JOIN_NODE",
            field: "hash_join_node",
        })?;
    let mut children = children.into_iter();
    let left = children.next().unwrap();
    let right = children.next().unwrap();
    refuse_carried_join_child(node, &left)?;
    refuse_carried_join_child(node, &right)?;

    // Validated before the conjuncts so an unsupported op is reported as such, rather than as
    // the missing conjuncts a folded-away predicate arrives with.
    let (join_type, output) = match join.join_op {
        TJoinOp::INNER_JOIN => (join_rel::JoinType::Inner, JoinOutput::Both),
        TJoinOp::LEFT_OUTER_JOIN => (join_rel::JoinType::Left, JoinOutput::Both),
        TJoinOp::RIGHT_OUTER_JOIN => (join_rel::JoinType::Right, JoinOutput::Both),
        TJoinOp::FULL_OUTER_JOIN => (join_rel::JoinType::Outer, JoinOutput::Both),
        TJoinOp::LEFT_SEMI_JOIN => (join_rel::JoinType::LeftSemi, JoinOutput::Left),
        TJoinOp::LEFT_ANTI_JOIN => (join_rel::JoinType::Left, JoinOutput::LeftAnti),
        TJoinOp::RIGHT_ANTI_JOIN => (join_rel::JoinType::Right, JoinOutput::RightAnti),
        TJoinOp::NULL_AWARE_LEFT_ANTI_JOIN => {
            (join_rel::JoinType::LeftMark, JoinOutput::NullAwareLeftAnti)
        }
        _ => {
            return Err(TranslateError::UnsupportedPlanNode {
                node_id: node.node_id,
                node_type: node.node_type,
                reason: "hash join type is unsupported",
            });
        }
    };

    let combined_tuples = [left.row_tuples.as_slice(), right.row_tuples.as_slice()].concat();
    let mut conditions = Vec::new();
    let mut first_equality = None;
    for eq in &join.eq_join_conjuncts {
        if let Some(opcode) = eq.opcode
            && opcode != TExprOpcode::EQ
        {
            return Err(TranslateError::UnsupportedPlanNode {
                node_id: node.node_id,
                node_type: node.node_type,
                reason: "only plain equality join conjuncts are supported",
            });
        }
        let mut expr_ctx = ctx.expr_context(&combined_tuples);
        let left_expr = eq.left.translate(&mut expr_ctx)?;
        let mut expr_ctx = ctx.expr_context(&combined_tuples);
        let right_expr = eq.right.translate(&mut expr_ctx)?;
        if first_equality.is_none() {
            first_equality = Some((left_expr.clone(), right_expr.clone()));
        }
        let anchor = ctx.registry.register_function(URN_COMPARISON, "equal");
        conditions.push(expr_translator::scalar_function(
            anchor,
            vec![left_expr, right_expr],
            crate::type_mapper::bool_type(),
        ));
    }
    for expr in join.other_join_conjuncts.as_deref().unwrap_or_default() {
        let mut expr_ctx = ctx.expr_context(&combined_tuples);
        conditions.push(expr.translate(&mut expr_ctx)?);
    }
    let condition = and_conditions(conditions, ctx).ok_or(TranslateError::UnsupportedPlanNode {
        node_id: node.node_id,
        node_type: node.node_type,
        reason: "hash join without join conjuncts",
    })?;

    let (row_tuples, output_width) = match output {
        JoinOutput::Left => (left.row_tuples.clone(), left.output_width),
        JoinOutput::NullAwareLeftAnti => (left.row_tuples.clone(), left.output_width + 1),
        _ => (
            combined_tuples.clone(),
            left.output_width + right.output_width,
        ),
    };

    let joined = TranslatedRel {
        rel: Rel {
            rel_type: Some(rel::RelType::Join(Box::new(JoinRel {
                left: Some(Box::new(left.rel)),
                right: Some(Box::new(right.rel)),
                expression: Some(Box::new(condition)),
                r#type: join_type as i32,
                ..Default::default()
            }))),
        },
        row_tuples,
        output_width,
        // Both children were refused above if they carried anything.
        carried_slots: Vec::new(),
    };
    let joined = match output {
        JoinOutput::LeftAnti => {
            let (_, right_key) = first_equality
                .ok_or_else(|| TranslateError::malformed("left anti join has no equality key"))?;
            let filtered = filter_is_null(joined, right_key, ctx);
            emit_columns(
                filtered,
                (0..left.output_width as i32).collect(),
                left.row_tuples,
            )
        }
        JoinOutput::RightAnti => {
            let (left_key, _) = first_equality
                .ok_or_else(|| TranslateError::malformed("right anti join has no equality key"))?;
            let filtered = filter_is_null(joined, left_key, ctx);
            let start = left.output_width as i32;
            let end = start + right.output_width as i32;
            emit_columns(filtered, (start..end).collect(), right.row_tuples)
        }
        JoinOutput::NullAwareLeftAnti => {
            let marker = field_selection(left.output_width as i32);
            let not_anchor = ctx.registry.register_function(URN_BOOLEAN, "not");
            let condition = expr_translator::scalar_function(
                not_anchor,
                vec![marker],
                crate::type_mapper::bool_type(),
            );
            let filtered = filter_rel(joined, condition);
            emit_columns(
                filtered,
                (0..left.output_width as i32).collect(),
                left.row_tuples,
            )
        }
        _ => joined,
    };
    // Node conjuncts are post-join predicates over the join's output row.
    apply_conjuncts(joined, node, ctx)
}

#[derive(Clone, Copy)]
enum JoinOutput {
    Both,
    Left,
    LeftAnti,
    RightAnti,
    NullAwareLeftAnti,
}

/// Refuses a join child that physically carries common-expr columns.
///
/// Join conjuncts resolve through `slot_global_index` over the concatenated child rows using
/// DESCRIPTOR materialized widths; a carried (wider-than-descriptor) child would physically
/// shift every right-side column while the descriptor math would not — a wrong column read,
/// not a type error the engine would catch. Consumers of a common slot across a join are
/// therefore refused, loudly, at translation.
fn refuse_carried_join_child(node: &TPlanNode, child: &TranslatedRel) -> Result<()> {
    if child.carried_slots.is_empty() {
        return Ok(());
    }
    let slots: Vec<i32> = child
        .carried_slots
        .iter()
        .map(|slot| slot.slot_id)
        .collect();
    Err(TranslateError::descriptor(format!(
        "{:?} {} reads a child that carries common-expr columns for slots {slots:?}; carried \
         columns would shift the join's combined descriptor row, so consumers of a common \
         slot across a join are not supported",
        node.node_type, node.node_id
    )))
}

/// Translates an inner/cross `NESTLOOP_JOIN_NODE` into an equality join on synthetic constants.
/// This preserves Cartesian-product semantics without requiring a GPU cross-product operator.
fn translate_nestloop_join(
    node: &TPlanNode,
    children: Vec<TranslatedRel>,
    ctx: &mut PlanContext<'_>,
) -> Result<TranslatedRel> {
    expect_children(node, &children, 2)?;
    let join = node
        .nestloop_join_node
        .as_ref()
        .ok_or(TranslateError::MissingField {
            context: "NESTLOOP_JOIN_NODE",
            field: "nestloop_join_node",
        })?;
